class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final (row, col) position to 0-indexed position
        # Position = row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store the count of balls for each color per player
        color_count = {}

        # Initialize empty dictionaries for each player
        for i in range(n):
            color_count[i] = {}

        # Process picks
        for player, color in pick:
            color_count[player][color] = color_count[player].get(color, 0) + 1

        # Count winning players
        winning_players = 0

        for player in range(n):
            # Find maximum count of any single color for this player
            max_count = max(color_count[player].values()) if color_count[player] else 0

            # Player wins if they have at least (player + 1) balls of same color
            if max_count >= player + 1:
                winning_players += 1

        return winning_players

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate minimum flips needed to make all rows palindromic
        rows_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare position j with position n-1-j
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate minimum flips needed to make all columns palindromic
        cols_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare position i with position m-1-i
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_flips += 1

        # Return the minimum of the two options
        return min(rows_flips, cols_flips)

