N, D = map(int, input().split())
points = []
for _ in range(N):
    x, y = map(int, input().split())
    points.append((x, y))

if D == 0:
    print(0)
else:
    x_coords = [p[0] for p in points]
    y_coords = [p[1] for p in points]

    x_coords.sort()
    y_coords.sort()

    # Function to calculate sum of absolute differences
    def sum_abs_x(x):
        return sum(abs(x - xi) for xi in x_coords)

    def sum_abs_y(y):
        return sum(abs(y - yi) for yi in y_coords)

    total_count = 0

    # We only need to check x values that are reasonable
    # The sum of distances grows linearly as we move away from the median
    # So we check x in a range around the median

    x_min, x_max = min(x_coords), max(x_coords)

    # Check x values in a reasonable range
    for x in range(x_min - 1000, x_max + 1001):
        sum_x = sum_abs_x(x)
        if sum_x > D:
            continue

        remaining = D - sum_x

        # For this x, count valid y values
        y_valid = 0
        for y in range(min(y_coords) - 1000, max(y_coords) + 1001):
            if sum_abs_y(y) <= remaining:
                y_valid += 1

        total_count += y_valid

    print(total_count)
